SELECT p.zadatel ,
       p."Registraèní èíslo projektu",
       p."IÈ",
       gg.czv,
       gg.eu,
       (gg.eu/gg.czv) as "Procento dotace",
       v."Èíslo výzvy",
       v."Název výzvy" ,
       SUBSTR(p.kompetencniutvar, 6) AS "Program podpory" ,
       -- hs.datumod AS "Datum RoPD",
       sum( rf.CASTKASCHVALENA ) AS  "Proplacená dotace" 

FROM isum.v_bi_UmzProjekt p 
INNER JOIN isum.v_bi_umzprjgg gg ON gg.id=p.id 
INNER JOIN isum.v_bi_UmzVyzva v ON v.id=p.id_vyzva 
INNER JOIN isum.v_bi_UmpPlatbaPrj platba ON p.id=platba.id_NositelPlatby
-- INNER JOIN isum.v_bi_UmsWFHistorieStavu hs ON hs.NositelId = p.id
INNER JOIN isum.v_bi_UmpRozpisFin rf ON rf.id_platba = platba.id AND rf.id_ukazatel = 361356  -- øádek 10aid_ukazatel = 361356  -- øádek 10ao   

WHERE p."Registraèní èíslo projektu" is not null 
-- AND hs.stavdo = 'PP30'
-- AND trunc(platba."Datum zmìny stavu") < to_date('2022-01-01','yyyy-mm-dd')
-- AND trunc(platba."Datum zmìny stavu") > to_date('2020-12-31','yyyy-mm-dd')
AND platba.kodwfstav in ('P10','P11')
AND rf.CASTKASCHVALENA > 0
AND p."Registraèní èíslo projektu" in ('CZ.01.3.15/0.0/0.0/17_095/0012569','CZ.01.3.15/0.0/0.0/17_095/0012592','CZ.01.3.15/0.0/0.0/17_095/0012702','CZ.01.3.15/0.0/0.0/17_095/0012703','CZ.01.3.15/0.0/0.0/17_095/0013047','CZ.01.3.15/0.0/0.0/17_095/0013050','CZ.01.3.15/0.0/0.0/17_095/0013065','CZ.01.3.15/0.0/0.0/17_095/0014343','CZ.01.3.15/0.0/0.0/17_095/0014360','CZ.01.3.15/0.0/0.0/17_095/0014436','CZ.01.2.06/0.0/0.0/17_117/0011893','CZ.01.2.06/0.0/0.0/17_117/0011894','CZ.01.2.06/0.0/0.0/17_117/0011895','CZ.01.2.06/0.0/0.0/17_117/0011896','CZ.01.2.06/0.0/0.0/17_117/0012842','CZ.01.2.06/0.0/0.0/17_117/0013009','CZ.01.2.07/0.0/0.0/17_118/0014331','CZ.01.2.07/0.0/0.0/17_118/0014332','CZ.01.2.07/0.0/0.0/17_118/0014364','CZ.01.2.07/0.0/0.0/17_118/0014365','CZ.01.2.07/0.0/0.0/17_118/0014371','CZ.01.2.07/0.0/0.0/17_118/0014372','CZ.01.2.07/0.0/0.0/17_118/0014547','CZ.01.2.07/0.0/0.0/17_118/0014715','CZ.01.1.02/0.0/0.0/17_121/0014419','CZ.01.1.02/0.0/0.0/17_121/0014422','CZ.01.1.02/0.0/0.0/17_121/0014424','CZ.01.1.02/0.0/0.0/17_123/0016945','CZ.01.1.02/0.0/0.0/17_125/0014246','CZ.01.1.02/0.0/0.0/17_125/0014413','CZ.01.1.02/0.0/0.0/17_125/0014421','CZ.01.1.02/0.0/0.0/17_125/0014426','CZ.01.2.06/0.0/0.0/17_139/0012655','CZ.01.2.06/0.0/0.0/17_139/0012716','CZ.01.2.06/0.0/0.0/17_139/0012800','CZ.01.2.06/0.0/0.0/17_139/0012813','CZ.01.2.06/0.0/0.0/17_139/0012815','CZ.01.2.06/0.0/0.0/17_139/0012816','CZ.01.2.06/0.0/0.0/17_139/0012817','CZ.01.2.06/0.0/0.0/17_139/0012838','CZ.01.2.06/0.0/0.0/17_139/0012841','CZ.01.2.06/0.0/0.0/17_139/0012850','CZ.01.2.06/0.0/0.0/17_139/0012865','CZ.01.2.06/0.0/0.0/17_139/0012869','CZ.01.2.06/0.0/0.0/17_139/0012870','CZ.01.2.06/0.0/0.0/17_139/0012871','CZ.01.2.06/0.0/0.0/17_139/0012888','CZ.01.2.06/0.0/0.0/17_139/0012928','CZ.01.2.06/0.0/0.0/17_139/0012932','CZ.01.2.06/0.0/0.0/17_139/0012952','CZ.01.2.06/0.0/0.0/17_139/0012984','CZ.01.2.06/0.0/0.0/17_139/0013073','CZ.01.2.06/0.0/0.0/17_139/0013078','CZ.01.2.06/0.0/0.0/17_139/0013097','CZ.01.2.06/0.0/0